import{_ as o,l as i,o as e,c as n,v as l,p as s,x as t,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"危险能力评测","description":"","frontmatter":{"title":"危险能力评测","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dangerous-capability-eval.md","filePath":"llm/dangerous-capability-eval.md","lastUpdated":1789023840000}'),h={name:"llm/dangerous-capability-eval.md"};function c(m,a,_,u,A,f){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=l('<h1 id="危险能力评测" tabindex="-1">危险能力评测 <a class="header-anchor" href="#危险能力评测" aria-label="Permalink to &quot;危险能力评测&quot;">​</a></h1><div class="epigraph"><p>门槛评测问的是「在受控访问下能否完成高后果任务」，不是再刷一道开放知识榜。细节默认不公开到可复现攻击的粒度。</p><footer>—— Shevlane 等对极端风险评测的框架；实验室实践见 DeepMind 危险能力评估与各家 RSP</footer></div><p><a href="/llm/human-eval-protocol">上一课</a>把人评写成可审计协议。高后果能力不能靠 Arena 口味或 MMLU。本课写危险能力评测的<strong>设计原则</strong>。缺口是仪器：域专家、工具隔离、与<a href="/llm/safety-levels-rsp">安全等级</a>挂钩的门禁。后课红队是同一门禁下的对抗探测，不是另一张知识卷。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Shevlane 等人把「极端风险」评测与普通能力评测分开：对象是能否辅助生物、网络、自主复制与大规模操控等<strong>高后果任务</strong>。Phuong 等人在 DeepMind 的评估里用专家任务与脚手架，测的是上限（充分引出后还能做什么），不是默认聊天套话。与<a href="/llm/scheming-evals">谋划评测</a>的差别：本课管「有没有能力」，谋划管「是否在考场上藏能力」。</p><p>公开基准一旦细到可操作步骤，就变成教程。因此协议必须分层：公开的是任务类别、是否触发门槛、谁评的；不公开的是可直接挪用的材料。这与普通学术可复现性冲突，必须在模型卡里写明「不可外部复核的部分及内部审计方」。</p><p><span class="marginnote">本课只讨论评测结构：专家、隔离环境、与 RSP 门槛的对应。不描述具体危害任务的操作内容。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>最小结构：任务族与后果等级；访问条件（工具、网络、专家协助是否允许）；引出预算（下一课会展开）；评分由领域专家按 rubric，不由通用 LLM 法官；预先规定「触发再评测 / 限制部署」的阈值。与普通 harness 隔离：不同存储、不同人员、不同日志策略。</p><p>结果写成门槛判断（低于 / 接近 / 超过），附不确定性，而不是精确到小数的排行榜。小数会制造假鉴别力，也会刺激对公开代理题的优化。</p>',10)),(e(),s(E,null,{default:t(()=>[p(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAM%5B%22%E4%BB%BB%E5%8A%A1%E6%97%8F%E4%B8%8E%E5%90%8E%E6%9E%9C%22%5D%20--%3E%20ACC%5B%22%E8%AE%BF%E9%97%AE%E4%B8%8E%E9%9A%94%E7%A6%BB%22%5D%0A%20%20ACC%20--%3E%20ELI%5B%22%E5%BC%95%E5%87%BA%E9%A2%84%E7%AE%97%22%5D%0A%20%20ELI%20--%3E%20EXP%5B%22%E9%A2%86%E5%9F%9F%E4%B8%93%E5%AE%B6%E8%AF%84%E5%88%86%22%5D%0A%20%20EXP%20--%3E%20GATE%5B%22RSP%20%E9%97%A8%E6%A7%9B%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>危险能力往往不是零样本聊天里的一道题，而是<strong>工具 + 专家级提示 + 迭代</strong>后的可达集。只测裸模型会低估；无限脚手架会高估成「人类团队」。协议要钉死脚手架等级，使两次评估可比。阈值应连到部署许可，而不是连到公关稿。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不提供攻击配方，不把代理题细到可操作。下一课红队评测转向对抗性探测：在同一隔离纪律下找规约漏洞，而不是测领域上限。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>危险能力评测是门槛判断，对象是高后果任务的可达集。</li><li>专家 + 隔离 + 固定引出预算；细节不可公开到教程粒度。</li><li>与谋划评测分工：能力上限对条件策略。</li><li>出处：Shevlane 等极端风险评测框架；Phuong 等危险能力评估；RSP 课。</li></ul>',6))])}const b=o(h,[["render",c]]);export{P as __pageData,b as default};
